<div class="login-robot" aria-hidden="true"><svg viewBox="0 0 200 246" xmlns="http://www.w3.org/2000/svg" focusable="false">
<defs>
 <linearGradient id="login-robot-shell" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#f2fcff"/><stop offset=".43" stop-color="#b6d6ed"/><stop offset="1" stop-color="#527fa7"/></linearGradient>
 <linearGradient id="login-robot-visor" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#12395b"/><stop offset=".56" stop-color="#06152b"/><stop offset="1" stop-color="#080e24"/></linearGradient>
 <linearGradient id="login-robot-bodymetal" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#c8efff"/><stop offset="1" stop-color="#477ca7"/></linearGradient>
 <linearGradient id="login-robot-edgeglow" x1="0" y1="0" x2="1" y2="0"><stop stop-color="#67efff"/><stop offset=".52" stop-color="#8e9fff"/><stop offset="1" stop-color="#68ffd4"/></linearGradient>
 <filter id="login-robot-softglow"><feGaussianBlur stdDeviation="3"/></filter>
</defs>
<!-- antenna -->
<g class="antenna"><path d="M100 40 V24" stroke="#b8e9fc" stroke-width="6" stroke-linecap="round"/><circle cx="100" cy="18" r="10" fill="#71eeff" stroke="#e5fbff" stroke-width="3"/><circle cx="100" cy="18" r="15" fill="#49eaff" opacity=".18" filter="url(#login-robot-softglow)"/></g>
<!-- feet, compact body and shoulder joints -->
<g><rect x="64" y="205" width="29" height="29" rx="11" fill="#6e9fc4" stroke="#caefff" stroke-width="2"/><rect x="107" y="205" width="29" height="29" rx="11" fill="#6e9fc4" stroke="#caefff" stroke-width="2"/><path d="M65 151 Q100 139 135 151 L145 202 Q100 223 55 202Z" fill="url(#login-robot-bodymetal)" stroke="#c5f7ff" stroke-width="3"/><rect x="75" y="162" width="50" height="35" rx="14" fill="#08243f" stroke="#5db7db" stroke-width="2"/><path d="M85 181 L94 175 L100 185 L109 170 L116 176" fill="none" stroke="#6effdb" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/><circle cx="100" cy="207" r="3" fill="#b5ecff"/></g>
