<g class="left-arm"><circle cx="56" cy="166" r="15" fill="#558eb7" stroke="#c4ecff" stroke-width="3"/><path d="M50 172 Q32 192 27 180" fill="none" stroke="#8cc4e7" stroke-width="19" stroke-linecap="round"/><circle cx="27" cy="180" r="12" fill="url(#login-robot-shell)" stroke="#b9f6ff" stroke-width="3"/></g>
<g class="right-arm"><circle cx="144" cy="166" r="15" fill="#558eb7" stroke="#c4ecff" stroke-width="3"/><path d="M152 167 Q179 160 176 135" fill="none" stroke="#8cc4e7" stroke-width="19" stroke-linecap="round"/><circle cx="176" cy="135" r="12" fill="url(#login-robot-shell)" stroke="#b9f6ff" stroke-width="3"/><path d="M171 127 L166 116 M178 123 L179 113" stroke="#bcecff" stroke-width="5" stroke-linecap="round"/></g>
<!-- side sensor pods -->
<rect x="9" y="75" width="23" height="53" rx="11" fill="#477d9f" stroke="#96dbff" stroke-width="3"/><rect x="168" y="75" width="23" height="53" rx="11" fill="#477d9f" stroke="#96dbff" stroke-width="3"/><rect x="13" y="88" width="6" height="25" rx="3" fill="#68eaff"/><rect x="181" y="88" width="6" height="25" rx="3" fill="#68eaff"/>
<!-- premium rounded helmet -->
<rect x="21" y="41" width="158" height="119" rx="49" fill="url(#login-robot-shell)" stroke="#e5faff" stroke-width="3"/>
<path d="M45 60 Q100 45 154 62" stroke="#fff" stroke-width="5" opacity=".55" fill="none" stroke-linecap="round"/>
<rect x="34" y="65" width="132" height="77" rx="33" fill="url(#login-robot-visor)" stroke="url(#login-robot-edgeglow)" stroke-width="3"/>
<path d="M51 77 Q100 69 151 80" fill="none" stroke="#80eaff" stroke-width="3" opacity=".19"/>
<!-- soft expressive LED eyes -->
<rect class="eye" x="62" y="88" width="17" height="29" rx="9" fill="#67f3ff"/><rect class="eye" x="121" y="88" width="17" height="29" rx="9" fill="#67f3ff"/>
<path d="M87 118 Q100 128 113 118" fill="none" stroke="#70ffdc" stroke-width="4" stroke-linecap="round"/>
<circle class="cheek" cx="49" cy="114" r="5" fill="#91a3ff"/><circle class="cheek" cx="151" cy="114" r="5" fill="#91a3ff"/>
<!-- bottom status lights -->
<rect x="80" y="148" width="40" height="4" rx="2" fill="#e5fbff" opacity=".55"/>
</svg></div>
